-- 044: skill dictionary v2. 251 skills (was 194), four broad skills tightened (Leadership, Sales, Regulatory
-- compliance, Research), and legal notices / pay and benefits text skipped before counting, so an equal-opportunity
-- statement no longer counts as "Regulatory compliance". Run after 043. Safe to re-run.
-- Source of truth: worker/rolearch_worker/data/skills.json (generated by scripts/skills-sql.py; the worker uses the
-- same file, so new jobs and the backfill agree).
-- Afterwards every open job is re-tagged by the existing 'skill-backfill' job (every 2 minutes, 25 seconds each),
-- about a week for ~1.7M jobs. Progress: select * from private.skill_backfill;

-- Boilerplate (legal notices, pay and benefits): sentences matching this are skipped before counting skills.
-- Same rule as strip_boilerplate() in worker/rolearch_worker/text.py.
create or replace function private.strip_boilerplate(p_text text)
returns text
language sql
immutable
set search_path = ''
as $fn$
  select coalesce(string_agg(piece, chr(10)), '')
  from regexp_split_to_table(coalesce(p_text, ''), '\n|[.!?;•]\s+') as piece
  where btrim(piece) <> '' and piece !~* '\yequal (?:employment )?opportunity\y|\yeeo\y|\yaffirmative action\y|\yamericans with disabilities\y|\yreasonable accommodations?\y|\yregardless of (?:race|age|sex|gender|religion|color|national)|\yprotected (?:veteran|status|characteristics?|class)\y|\yveteran status\y|\ysexual orientation\y|\ygender identity\y|\yfair chance\y|\ycriminal (?:history|histories|background)\y|\ye-verify\y|\ypay (?:range|transparency|scale)\y|\ysalary range\y|\ybase (?:pay|salary)(?: range)?\y|\ycompensation (?:range|package)\y|\yhourly rate\y|\ybenefits (?:include|package|offered)\y|\y401\(?k\)?|\ypaid time off\y|\ypto\y|\y(?:medical|health), dental\y|\ydental(?:,| and) vision\y|\yemployee assistance\y|\ytuition (?:reimbursement|assistance)\y|\yparental leave\y|\ylife insurance\y|\ydisability insurance\y|\yhealth savings\y|\yflexible spending\y|\ystock purchase\y|\yprivacy (?:notice|policy|statement)\y|\ynot intended to be (?:an )?(?:all-inclusive|exhaustive|comprehensive)\y|\ymay be (?:changed|modified|amended) at any time\y|\ythis job description\y|\yto request an accommodation\y|\ydiverse and inclusive\y|\ydiversity,? (?:equity|and inclusion)\y|\ywe are proud to be\y|\ywe(?: are|''re) committed to (?:creating|building|providing|fostering|diversity|equal)|\yrecruitment (?:agencies|fraud|scam)\y|\yai screening\y|\y(?:use|uses|using) ai(?: tools)? (?:to|in|for) (?:support |assist (?:with |in )?)?(?:candidate|hiring|recruit|screening|the hiring)|\yunsolicited resumes?\y'
$fn$;

truncate private.skill_patterns;
-- Skills are counted on the job text with boilerplate removed (top 12, like the worker).
create or replace function private.top_skills(p_text text)
returns text[]
language sql
stable
set search_path = ''
as $$ select (private.extract_skills(private.strip_boilerplate(p_text)))[1:12] $$;

revoke all on function private.strip_boilerplate(text) from public, anon, authenticated;

-- Re-tag every open job with the new dictionary (the backfill job picks this up within 2 minutes).
update private.skill_backfill set last_id = '', done = false, processed = 0, updated_at = now() where id = 1;
